@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#131615;--panel:#1b201e;--panel-hi:#212725;--line:#343c38;--muted:#8a938d;--paper:#e9e9de;--acid:#d8f36a;--orange:#f2a471;--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif}*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:var(--ink);color:var(--paper);font:13px var(--sans);overflow:hidden}.app-shell{height:100vh;min-height:650px;display:grid;grid-template-rows:58px 1fr 36px;background:radial-gradient(ellipse at 52% 43%,#252b28 0,#171b19 45%,#111413 100%)}.topbar{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 30px;border-bottom:1px solid #303633;background:#141816;position:relative;z-index:2}.brand{display:flex;gap:10px;align-items:center;color:var(--paper);text-decoration:none;font-size:13px;font-weight:800;letter-spacing:.13em}.brand-mark{width:24px;height:24px;background:var(--acid);color:#182018;display:grid;place-items:center;font-size:15px;clip-path:polygon(0 0,100% 0,100% 72%,72% 100%,0 100%)}.brand-slash{color:var(--acid)}.top-center,.sound-toggle,.eyebrow,.preview-caption,.scene-label,.step-summary,.component-count,.subtotal span,.statusbar,.option-meta,.option-price,.crystal-readout small,.price-readout small,.sale-total span,.sale-total small,.sale-breakdown{font-family:var(--mono);letter-spacing:.07em}.top-center{font-size:9px;color:#8f9992;letter-spacing:.12em;position:absolute;left:50%;transform:translateX(-50%)}.live-dot,.status-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--acid);box-shadow:0 0 9px #d8f36a88;margin-right:8px;vertical-align:1px}.top-divider{color:#535c56;margin:0 8px}.sound-toggle{background:none;border:0;color:#a6afa8;font-size:9px;display:flex;align-items:center;gap:9px;cursor:pointer}.sound-toggle b{font-weight:400;color:#69736c}.sound-toggle.enabled b{color:var(--acid)}.sound-icon{font:18px var(--sans);color:var(--acid)}.workspace{display:grid;grid-template-columns:minmax(230px,270px) minmax(400px,1fr) minmax(285px,335px);gap:0;min-height:0;padding:16px 20px 14px}.left-rail{padding:10px 24px 0 10px;display:flex;flex-direction:column;min-width:0}.rail-heading{display:flex;justify-content:space-between;align-items:flex-end}.eyebrow{display:block;color:#9da79f;font-size:8px;letter-spacing:.14em}.rail-heading h1{font-size:33px;line-height:1.04;letter-spacing:-.065em;margin:12px 0 0;font-weight:600}.rail-heading h1 em,.sale-card h2 em{font-family:Georgia,serif;font-weight:400;color:var(--acid)}.build-number{font:10px var(--mono);text-align:right;color:var(--paper);line-height:1.55;padding-bottom:4px}.build-number span{color:#69736d}.intro-copy{font-size:11px;line-height:1.8;color:#9aa39c;max-width:215px;margin:17px 0 22px}.progress-track{height:2px;background:#333b36;width:100%;margin-bottom:20px}.progress-fill{height:100%;width:20%;background:var(--acid);transition:width .35s}.step-list{display:flex;flex-direction:column;gap:5px}.step-item{border:1px solid transparent;background:transparent;color:#929b94;display:flex;align-items:center;gap:12px;padding:11px 9px;text-align:left;cursor:pointer;transition:.2s;font-family:var(--sans)}.step-item:hover{background:#1b211e}.step-item.active{border-color:#3a443b;background:#202722;color:var(--paper)}.step-item.done .step-index{color:var(--acid);border-color:#637148}.step-index{width:24px;height:24px;border:1px solid #414a44;display:grid;place-items:center;font:9px var(--mono);color:#7b847e;flex:none}.step-copy{display:flex;flex-direction:column;gap:4px}.step-copy strong{font-size:11px;font-weight:600}.step-copy small{font:8px var(--mono);color:#78817a;letter-spacing:.06em}.step-state{margin-left:auto;font-size:11px;color:var(--acid)}.rail-bottom{margin-top:auto;color:#66716a;font:8px var(--mono);letter-spacing:.09em;padding:12px 0 10px;display:flex;align-items:center;gap:8px}.tiny-orbit{font-size:16px;color:var(--acid)}
.preview-panel{border:1px solid #39413c;background:linear-gradient(150deg,#222825,#191e1c 78%);position:relative;display:grid;grid-template-rows:48px minmax(0,1fr) 68px 54px;min-width:0;overflow:hidden}.preview-top{position:absolute;z-index:1;top:15px;left:18px;right:18px;display:flex;justify-content:space-between;align-items:center}.preview-top>div{display:flex;align-items:center;gap:13px}.preview-caption{font-size:8px;color:#849087}.preview-caption span{color:var(--acid);font-size:12px}.icon-button{width:29px;height:29px;border:1px solid #48514b;color:#b5beb6;background:#1a201d;font-size:18px;cursor:pointer;transition:.2s}.icon-button:hover{color:var(--acid);border-color:var(--acid)}.scene-wrap{position:relative;min-height:300px;overflow:hidden;background:radial-gradient(ellipse at 51% 47%,#39443d 0,#242b27 32%,#1d2320 67%,#1a1f1d 100%)}.scene-wrap:before{content:"";position:absolute;inset:0;background-image:linear-gradient(#cbd7c008 1px,transparent 1px),linear-gradient(90deg,#cbd7c008 1px,transparent 1px);background-size:50px 50px;transform:perspective(360px) rotateX(60deg) scale(1.7);transform-origin:50% 80%;opacity:.55;mask-image:linear-gradient(to bottom,transparent 12%,#000 85%)}.scene-wrap canvas{position:absolute;inset:0;width:100%;height:100%;z-index:1;cursor:grab}.scene-wrap canvas:active{cursor:grabbing}.scene-vignette{position:absolute;inset:0;z-index:2;pointer-events:none;background:radial-gradient(ellipse at center,transparent 40%,#14181666 100%)}.scene-loading{position:absolute;z-index:4;inset:0;display:grid;place-content:center;justify-items:center;gap:12px;background:#1c221f;color:#a6b0a7;font:9px var(--mono);letter-spacing:.12em;transition:opacity .5s}.scene-loading span{width:24px;height:24px;border:1px solid #657155;border-top-color:var(--acid);border-radius:50%;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.scene-label{position:absolute;left:17px;bottom:15px;z-index:3;font-size:8px;color:#a6b0a7}.scene-label-rig