.choice-panel{border:1px solid #343c37;border-left:0;background:#1b201e;padding:22px 19px 0;display:flex;flex-direction:column;min-width:0}.choice-header{display:flex;justify-content:space-between;align-items:flex-end}.choice-header h2{font-size:19px;letter-spacing:-.04em;margin:8px 0 0;font-weight:600}.component-count{font-size:12px;color:var(--paper);padding-bottom:2px}.component-count i{font-style:normal;color:#758078;font-size:9px}.choice-description{font-size:10px;line-height:1.7;color:#909a92;margin:11px 0 19px;max-width:260px;min-height:34px}.option-list{display:flex;flex-direction:column;gap:8px}.option-card{position:relative;border:1px solid #373f3a;background:#202623;padding:11px 10px;cursor:pointer;transition:border-color .2s,background .2s;display:grid;grid-template-columns:37px 1fr auto;align-items:center;gap:10px;text-align:left;color:var(--paper);font-family:var(--sans);min-height:66px}.option-card:hover{border-color:#727d6d;background:#252d28}.option-card.selected{border-color:var(--acid);background:#262e27}.option-card.selected:after{content:"✓";position:absolute;right:8px;top:5px;color:var(--acid);font-size:9px}.option-swatch{height:39px;width:37px;background:linear-gradient(140deg,#818780,#303633 50%,#757c73);position:relative;overflow:hidden}.option-swatch:before{content:"";position:absolute;inset:6px 12px;border-left:2px solid #d5dad1;border-right:2px solid #7a8279;opacity:.65}.option-swatch:after{content:"";position:absolute;left:0;right:0;top:50%;height:2px;background:#171c19;box-shadow:0 4px #aab0a6}.option-swatch.copper{background:linear-gradient(140deg,#d9a77e,#514034 50%,#ac7550)}.option-swatch.onyx{background:linear-gradient(140deg,#747b78,#1a201e 50%,#434b46)}.option-swatch.ivory{background:linear-gradient(140deg,#e1dcc6,#666252 55%,#c2baa4)}.option-swatch.ridged:after{top:23%;height:2px;box-shadow:0 5px #171c19,0 10px #aab0a6,0 15px #171c19}.option-swatch.crystal{background:radial-gradient(circle,#6070ff 0,#384a5c 32%,#202623 72%)}.option-swatch.crystal:before{inset:7px 12px;background:#81aaff;clip-path:polygon(50% 0,100% 30%,82% 100%,18% 100%,0 30%);box-shadow:0 0 10px #82aaff}.option-swatch.crystal:after{display:none}.option-copy{display:flex;flex-direction:column;gap:4px;padding-right:3px}.option-copy strong{font-size:10px;font-weight:600}.option-copy small{font:8px var(--mono);color:#818b83;letter-spacing:.04em}.option-price{font-size:9px;color:#d4dacf;align-self:start;padding-top:3px}.option-card.selected .option-price{color:var(--acid)}.selection-note{margin-top:14px;padding:10px 9px;display:flex;align-items:flex-start;gap:9px;background:#232925;color:#99a39b;font-size:9px;line-height:1.6}.note-icon{color:var(--acid);font-size:13px;line-height:1}.choice-footer{margin-top:auto;border-top:1px solid #373f3a;padding:14px 0 15px;display:flex;align-items:center;justify-content:space-between;gap:8px}.subtotal{display:flex;flex-direction:column;gap:5px}.subtotal span{font-size:7px;color:#808a82}.subtotal strong{font:12px var(--mono);color:var(--acid)}.primary-button.wide{font-size:9px;padding:13px 10px;flex:1}.primary-button.wide span{margin-left:7px}
